46	/**
47	 * MDX 2 requires escaping { with a \ so our anchor syntax need that now.
48	 * See https://mdxjs.com/docs/troubleshooting-mdx/#could-not-parse-expression-with-acorn-error
49	 */
50	export function escapeMarkdownHeadingIds(content: string): string {
51	  const markdownHeadingRegexp = /(?:^|\n)#{1,6}(?!#).*/g;
52	  return content.replaceAll(markdownHeadingRegexp, (substring) =>
53	    // TODO probably not the most efficient impl...
54	    substring
55	      .replace('{#', '\\{#')
56	      // prevent duplicate escaping
57	      .replace('\\\\{#', '\\{#'),
58	  );
59	}
