62	 * Hacky temporary escape hatch for Crowdin bad MDX support
63	 * See https://docusaurus.io/docs/i18n/crowdin#mdx
64	 *
65	 * TODO Titus suggested a clean solution based on ```mdx eval and Remark
66	 * See https://github.com/mdx-js/mdx/issues/701#issuecomment-947030041
67	 *
68	 * @param content
69	 */
70	export function unwrapMdxCodeBlocks(content: string): string {
71	  // We only support 3/4 backticks on purpose, should be good enough
72	  const regexp3 =
73	    /(?<begin>^|\r?\n)(?<indentStart>\x20*)```(?<spaces>\x20*)mdx-code-block\r?\n(?<children>.*?)\r?\n(?<indentEnd>\x20*)```(?<end>\r?\n|$)/gs;
74	  const regexp4 =
75	    /(?<begin>^|\r?\n)(?<indentStart>\x20*)````(?<spaces>\x20*)mdx-code-block\r?\n(?<children>.*?)\r?\n(?<indentEnd>\x20*)````(?<end>\r?\n|$)/gs;
76	
77	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
78	  const replacer = (substring: string, ...args: any[]) => {
79	    const groups = args.at(-1);
80	    return `${groups.begin}${groups.children}${groups.end}`;
81	  };
82	
83	  return content.replaceAll(regexp3, replacer).replaceAll(regexp4, replacer);
84	}
